using System;using System.Diagnostics;using System.IO;using System.Reflection;using System.Security.Principal;using System.Threading;using System.Web.Script.Serialization;
internal static class EmbeddedFollowTests {
 static int checks;static void Need(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
 static bool Watch(string root,string state){string name=(string)typeof(CodexFollow).GetMethod("Name",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{"Watch",root,state});try{using(var mutex=Mutex.OpenExisting(name))return true;}catch(WaitHandleCannotBeOpenedException){return false;}}
 static bool Until(Func<bool> condition,int milliseconds=3000){var clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<milliseconds){if(condition())return true;Thread.Sleep(20);}return condition();}
 static int Starts(string path){return File.Exists(path)?File.ReadAllLines(path).Length:0;}
 static int Main(string[] args){string root=args[0],state=args[1],package=args[2],report=args[3];try{var json=new JavaScriptSerializer();Directory.CreateDirectory(state);File.WriteAllText(Path.Combine(root,".codex-background-install.json"),json.Serialize(new{productId="codex-live-background/exe",root}));File.WriteAllText(Path.Combine(state,"pet-settings.json"),"{\"FollowCodex\":true}");
  Need(CodexFollow.InstalledHere(root),"Owned installation rejected");Need(!CodexFollow.InstalledHere(Path.Combine(root,"missing")),"Uninstalled root accepted");string sid=WindowsIdentity.GetCurrent().User.Value;
  using(var managerPresence=new Mutex(false,"Local\\CodexLiveBackground.Manager."+sid))using(var follow=CodexFollow.StartEmbedded(root,state)){Need(Until(()=>Watch(root,state)),"Embedded follow did not acquire its own watch");var clock=Stopwatch.StartNew();CodexFollow.ManualExit(root,state);Need(clock.ElapsedMilliseconds<2000,"Embedded manual-exit acknowledgement timed out");using(var pause=CodexFollow.Suspend(root,state)){CodexFollow.StopAndWait(root,state);Need(Until(()=>!Watch(root,state)),"Embedded follow did not yield during update");Thread.Sleep(850);Need(!Watch(root,state),"Embedded follow restarted during maintenance");}Need(Until(()=>Watch(root,state)),"Embedded follow did not resume after maintenance");File.WriteAllText(Path.Combine(state,"pet-settings.json"),"{\"FollowCodex\":false}");Need(Until(()=>!Watch(root,state)),"Disabled preference leaves follow active");}
  using(var legacy=Process.Start(new ProcessStartInfo(Path.Combine(package,"CodexHubUpdater.exe"),"--follow \""+state+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){Need(legacy.WaitForExit(2000)&&legacy.ExitCode==0,"Legacy updater remains resident");}
  string guard=Path.Combine(root,@"startup\DreamSkinPortHook.exe"),counter=Path.Combine(root,@"startup\fixture-starts.txt"),stop=Path.Combine(root,@"startup\stop-guard");using(var old=Process.Start(new ProcessStartInfo(guard){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){Need(Until(()=>Starts(counter)==1),"Owned guard fixture did not start");using(var update=new GuardSoftwareMaintenance(root)){Need(old.HasExited&&File.Exists(stop),"Program update did not stop its guard cooperatively");}Need(Until(()=>Starts(counter)==2),"Program update did not restore its guard");File.WriteAllText(stop,"fixture complete");Need(Until(()=>Array.FindAll(Process.GetProcessesByName("DreamSkinPortHook"),p=>{try{using(p)return p.MainModule.FileName.Equals(guard,StringComparison.OrdinalIgnoreCase);}catch{return false;}}).Length==0),"Owned guard fixture survived cleanup");}
  File.WriteAllText(report,json.Serialize(new{pass=true,checks,embeddedFollow=true,updaterNotResident=true,cooperativeGuardUpdate=true,realCodexManipulated=false,realRegistrationChanged=false}));return 0;
 }catch(Exception error){File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{pass=false,checks,error=error.ToString()}));return 1;}}
}
